using GraphApi.Models.TKT.ComentariosTicket;namespace GraphApi.Services.TKT.ComentariosTicket{    /// <summary>    /// Define las operaciones de negocio y persistencia para ComentariosTickets.    /// </summary>    public interface IComentariosTicketService    {        /// <summary>        /// Obtiene la lista de ComentariosTickets con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadComentariosTicket>> GetComentariosTickets(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de ComentariosTickets con filtros opcionales.        /// </summary>        /// <param name="comentarioTicketID">Filtro opcional para ComentarioTicketID.</param>        /// <param name="ticketID">Filtro opcional para TicketID.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="comentario">Filtro opcional para Comentario.</param>        /// <param name="fechaComentario">Filtro opcional para FechaComentario.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetComentariosTicketsDynamic(            int? comentarioTicketID,            int? ticketID,            int? usuarioID,            string? comentario,            DateTime? fechaComentario,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo ComentariosTicket.        /// </summary>        /// <param name="objInput">Datos para crear el ComentariosTicket.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadComentariosTicket> CreateComentariosTicket(            clCreateComentariosTicket objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un ComentariosTicket.        /// </summary>        /// <param name="objInput">Datos para actualizar el ComentariosTicket, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadComentariosTicket?> UpdateComentariosTicket(            clUpdateComentariosTicket objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un ComentariosTicket por su ID.        /// </summary>        /// <param name="nComentariosTicketID">ID del ComentariosTicket a eliminar.</param>        Task<bool> DeleteComentariosTicket(int nComentariosTicketID);    }}